import openpyxl,glob,re
pat=re.compile(r'salary|salaries|remunerat|compensat|okonkwo|CFO|director.*emolument|pay\b|bonus|wage', re.I)
for f in sorted(glob.glob('*.xlsx')):
    wb=openpyxl.load_workbook(f,data_only=True)
    for ws in wb:
        for row in ws.iter_rows():
            for c in row:
                if isinstance(c.value,str) and pat.search(c.value):
                    print(f,'|',ws.title,'|',c.coordinate,'|',c.value[:120])
"

