from pptx import Presentation
import sys,re
p=Presentation(sys.argv[1])
pat=re.compile(r'salar|remunerat|compensat|okonkwo|CFO|pay|bonus|wage',re.I)
for i,s in enumerate(p.slides,1):
    for sh in s.shapes:
        if sh.has_text_frame and pat.search(sh.text_frame.text):
            print(i, sh.text_frame.text[:300])
" "$f"; done
